/**
 * Map backend entities to the locally seeded imagery in public/seed/
 * (generated by `npm run seed`). Backend listings carry no photos yet, so each
 * property gets a deterministic, category-appropriate set of images.
 */

const PER_CATEGORY = 4;
const KNOWN = ["house", "villa", "apartment", "tower", "office", "shop", "plot", "farmhouse", "building", "floor", "space", "mall"];

function hash(s: string): number {
  let h = 2166136261;
  for (let i = 0; i < s.length; i++) h = Math.imul(h ^ s.charCodeAt(i), 16777619);
  return h >>> 0;
}

type Imageable = { id?: string; title?: string; category?: string | null; image_urls?: string[]; kanal_area?: number | null; price?: number };

function categoryFor(p: Imageable): string {
  const c = (p.category ?? "").toLowerCase();
  const t = (p.title ?? "").toLowerCase();
  if (t.includes("farmhouse")) return "farmhouse";
  if (c === "house" && ((p.kanal_area ?? 0) >= 1 || (p.price ?? 0) >= 80_000_000)) return "villa";
  if (KNOWN.includes(c)) return c;
  if (/(tower|mall|plaza)/.test(t)) return "tower";
  return "house";
}

/** Primary cover image for a property. Real uploaded images win over seeds. */
export function coverImage(p: Imageable): string {
  if (p.image_urls?.length) return p.image_urls[0]!;
  const cat = categoryFor(p);
  const n = (hash(p.id ?? p.title ?? cat) % PER_CATEGORY) + 1;
  return `/seed/properties/${cat}-${n}.svg`;
}

/** Gallery: exterior variants + interiors + a floor plan. */
export function gallery(p: Imageable): string[] {
  if (p.image_urls && p.image_urls.length > 1) return p.image_urls;
  const cat = categoryFor(p);
  const h = hash(p.id ?? p.title ?? cat);
  const ext = Array.from({ length: PER_CATEGORY }, (_, i) => `/seed/properties/${cat}-${((h + i) % PER_CATEGORY) + 1}.svg`);
  const isLand = cat === "plot";
  const interiors = isLand ? [] : [0, 1, 2].map((i) => `/seed/interiors/interior-${((h + i) % 6) + 1}.svg`);
  const plan = isLand ? [] : [`/seed/plans/plan-${(h % 3) + 1}.svg`];
  return [...ext.slice(0, 3), ...interiors, ...plan];
}

export function cityImage(name?: string | null): string {
  const n = (name ?? "").toLowerCase();
  if (["lahore", "karachi", "islamabad", "rawalpindi"].includes(n)) return `/seed/cities/${n}.svg`;
  return `/seed/cities/rawalpindi.svg`;
}

/** Image for a scheme / big project / story, chosen by keyword then hash. */
export function themedImage(key: string, hint?: string | null): string {
  const h = (hint ?? "").toLowerCase();
  let cat = "building";
  if (/(mall|plaza|arcade|retail|shop)/.test(h)) cat = "mall";
  else if (/(tower|office|corporate|tech)/.test(h)) cat = "tower";
  else if (/(compound|villa|garden|housing|residence|home|house)/.test(h)) cat = "villa";
  else if (/(apartment|flat|heights)/.test(h)) cat = "apartment";
  else if (/(plot|land|farm)/.test(h)) cat = "plot";
  return `/seed/properties/${cat}-${(hash(key) % PER_CATEGORY) + 1}.svg`;
}

